#!/usr/bin/env node
/**
 * thienui-guards — chạy mọi cổng UI trên một repo.
 *
 * Đặt vào `verify` của project tiêu thụ:
 *   "verify": "... && thienui-guards"
 *
 * Cờ:
 *   --root <đường dẫn>      repo cần quét (mặc định: cwd)
 *   --tokens <file.json>    tokens.json đã build (mặc định: tự tìm trong node_modules hoặc workspace)
 *   --patterns <file.json>  registry luật (mặc định: tự tìm)
 *   --report                in đủ bảng đo, kể cả ca đã pass
 */
import { existsSync, readFileSync } from 'node:fs';
import { resolve, join } from 'node:path';
import { checkContrast, checkGamut } from '../src/contrast.mjs';
import { runPatternLock } from '../src/pattern-lock.mjs';
import { checkCanonicals } from '../src/canonical.mjs';

const argv = process.argv.slice(2);
const flag = (n, d = null) => {
  const i = argv.indexOf('--' + n);
  return i === -1 ? d : argv[i + 1];
};
const has = (n) => argv.includes('--' + n);

const root = resolve(flag('root', process.cwd()));

/** Tự tìm một file ở các chỗ thường gặp: node_modules (project tiêu thụ) hoặc workspace (trong repo). */
function locate(explicit, candidates, what) {
  if (explicit) {
    const p = resolve(explicit);
    if (!existsSync(p)) fail(`không thấy ${what}: ${p}`);
    return p;
  }
  for (const c of candidates) {
    const p = resolve(root, c);
    if (existsSync(p)) return p;
  }
  fail(`không tự tìm được ${what}. Truyền đường dẫn bằng cờ tương ứng.\n  đã thử:\n` + candidates.map((c) => '    ' + c).join('\n'));
}

function fail(msg) {
  console.error('\n✗ thienui-guards: ' + msg + '\n');
  process.exit(2);
}

const tokensPath = locate(flag('tokens'), [
  'node_modules/@thienui/tokens/dist/tokens.json',
  'tooling/thienui-guards/tokens.json',
  'packages/tokens/dist/tokens.json',
  '../tokens/dist/tokens.json',
], 'tokens.json');

const patternsPath = locate(flag('patterns'), [
  'node_modules/@thienui/ui-patterns/src/ui-patterns.json',
  'tooling/thienui-guards/ui-patterns.json',
  'packages/ui-patterns/src/ui-patterns.json',
  '../ui-patterns/src/ui-patterns.json',
  'docs/ui-patterns.json',
], 'ui-patterns.json');

/**
 * Luật là của chính repo này (thienui), hay ĐƯỢC PHÁT tới project tiêu thụ — qua node_modules (npm)
 * hoặc qua `tooling/thienui-guards/` (registry item `guards` chép vào)?
 */
const parts = patternsPath.split(/[\\/]/);
const ownsRegistry = !parts.includes('node_modules') && !parts.includes('thienui-guards');

const tokens = JSON.parse(readFileSync(tokensPath, 'utf8'));
const registry = JSON.parse(readFileSync(patternsPath, 'utf8'));

let exitCode = 0;
const bar = '─'.repeat(72);

/* ───────── cổng 1: gamut ───────── */
const gamut = checkGamut(tokens);
if (!gamut.pass) {
  exitCode = 1;
  console.error('\n' + bar + '\n✗ GAMUT — token khai màu ngoài sRGB, máy không hiện được đúng màu đó\n' + bar);
  for (const b of gamut.outOfGamut) console.error(`  ${b.path}  ${b.value}`);
}

/* ───────── cổng 2: contrast ───────── */
const c = checkContrast(tokens);
const byTier = (t) => c.results.filter((r) => r.tier === t).length;
if (!c.pass) {
  exitCode = 1;
  console.error('\n' + bar + '\n✗ CONTRAST — ' + c.failures.length + '/' + c.results.length + ' cặp trượt sàn WCAG\n' + bar);
  for (const f of c.failures) {
    console.error(`  ${f.theme}/${f.mode}  --${f.fg} trên --${f.bg}`);
    console.error(`      đo ${f.ratio} · cần ${f.floor} · ${f.where}`);
    if (f.reason) console.error(`      ${f.reason}`);
  }
  console.error('\n  Sửa TOKEN, đừng chuyển một cặp chữ xuống bậc đồ hoạ cho cổng im tiếng.');
  console.error('  Dùng solveLightness() trong @thienui/guards để giải L thay vì mò bằng tay.');
}

/* ───────── cổng 3: pattern lock ───────── */
const pl = runPatternLock(root, registry);
if (!pl.pass) {
  exitCode = 1;
  console.error('\n' + bar + '\n✗ UI PATTERN LOCK — ' + pl.total + ' vi phạm luật đã khoá\n' + bar);
  for (const p of pl.byPattern) {
    if (!p.violations.length) continue;
    console.error(`\n  [${p.id}]  ${p.rule}`);
    if (p.canonical) console.error(`  làm đúng ở: ${p.canonical}${ownsRegistry ? '' : '  (trong repo thienui)'}`);
    for (const v of p.violations.slice(0, 8)) console.error(`    ${v.file}:${v.line}  ${v.excerpt}`);
    if (p.violations.length > 8) console.error(`    … và ${p.violations.length - 8} chỗ nữa`);
  }
}
for (const p of pl.byPattern) {
  if (p.error) {
    exitCode = 1;
    console.error(`\n✗ luật [${p.id}] lỗi cấu hình: ${p.error}`);
  }
}

/* ───────── cổng 4: canonical phải có thật ───────── */
// Cổng này kiểm REGISTRY LUẬT, không kiểm repo đang quét: `canonical` là đường dẫn bên trong thienui.
// Ở project tiêu thụ (luật đến từ node_modules hoặc tooling/thienui-guards/) mọi con trỏ đều "không tồn tại" theo định nghĩa, và
// một cổng đỏ vì lý do người tiêu thụ không sửa được sẽ dạy họ tắt cổng. Registry được kiểm ở CI
// của chính thienui; ở đây `canonical` chỉ in ra như con trỏ vào mã nguồn thienui.
const can = ownsRegistry ? checkCanonicals(root, registry) : { pass: true, skipped: true };
if (!can.pass) {
  exitCode = 1;
  console.error('\n' + bar + '\n✗ CANONICAL — luật trỏ "làm đúng ở" vào chỗ không tồn tại\n' + bar);
  for (const m of can.missing) console.error(`  [${m.id}]  ->  ${m.canonical}`);
  for (const id of can.noCanonical) console.error(`  [${id}]  thiếu hẳn trường canonical (dùng "—" nếu cố ý)`);
  console.error('\n  Một luật trỏ vào file không có thì tệ hơn một luật không có con trỏ: người đọc mở ra,');
  console.error('  không thấy gì, rồi kết luận luật đã lỗi thời và bỏ qua nó.');
}

/* ───────── tổng kết ───────── */
const manual = pl.byPattern.filter((p) => p.manual).length;
const auto = pl.byPattern.length - manual;
if (has('report')) {
  console.log('\n' + bar + '\nBẢNG ĐO CONTRAST\n' + bar);
  let last = '';
  for (const r of c.results) {
    const k = `${r.theme}/${r.mode}`;
    if (k !== last) { console.log(`\n  ${k}`); last = k; }
    const mark = r.pass ? '·' : '✗';
    const floor = r.floor ? `/ cần ${r.floor}` : '/ bậc decor, không có sàn';
    console.log(`    ${mark} --${r.fg} trên --${r.bg}  ${String(r.ratio).padEnd(7)} ${floor}`);
  }
}
if (exitCode === 0) {
  console.log(
    `✓ guards: ${c.results.length} cặp contrast (${byTier('text')} chữ · ${byTier('graphic')} đồ hoạ · ${byTier('decor')} decor) ` +
      `· ${auto} luật máy kiểm + ${manual} luật review · gamut sạch · ${can.skipped ? 'canonical: kiểm ở thienui' : 'canonical đủ'}`
  );
} else {
  console.error('');
}
process.exit(exitCode);

/**
 * Cổng: mỗi luật phải trỏ `canonical` vào một chỗ CÓ THẬT.
 *
 * Vì sao đây là một cổng chứ không phải chuyện nhỏ: `canonical` là câu trả lời cho "vậy làm đúng thì
 * trông thế nào?". Một luật trỏ vào file không tồn tại thì tệ hơn một luật không có con trỏ — người
 * đọc (hoặc agent) mở ra, không thấy gì, rồi kết luận luật đã lỗi thời và bỏ qua nó. Cả cụm luật
 * chết theo cách đó mà không ai sửa gì.
 *
 * Lúc dựng pha 4, cổng này bắt được 14/32 luật đang trỏ vào chỗ không có.
 */
import { existsSync } from 'node:fs';
import { join } from 'node:path';

/** Nơi thử tìm một đường dẫn canonical, theo thứ tự. */
const ROOTS = ['', 'apps/docs', 'packages'];

/** `—` nghĩa là luật CỐ Ý không có canonical (luật về thái độ, không về một file). */
const NONE = '—';

export function checkCanonicals(root, registry) {
  const missing = [];
  const noCanonical = [];
  for (const p of registry.patterns) {
    const c = p.canonical;
    if (!c) {
      noCanonical.push(p.id);
      continue;
    }
    if (c === NONE) continue;
    const found = ROOTS.some((r) => existsSync(join(root, r, c)));
    if (!found) missing.push({ id: p.id, canonical: c });
  }
  return { pass: missing.length === 0 && noCanonical.length === 0, missing, noCanonical };
}

/**
 * Cổng tương phản WCAG trên TOKEN, cho mọi theme × mọi mode.
 *
 * Khác hai điểm so với bản trong sakubun, và cả hai là sửa lỗi thật:
 *
 *  1. ĐỌC DỮ LIỆU, KHÔNG PARSE CSS. Bản cũ đọc `app/globals.css` theo TỪNG DÒNG, nên một lần
 *     `prettier --write` gấp dòng khai `--muted-foreground` thành ba đã làm 4 ca đỏ với
 *     `TypeError: ... reading 'startsWith'`, và lập tức sinh ra một chú thích "GIỮ TRÊN MỘT DÒNG"
 *     trong file CSS. Cổng nào mà format code làm vỡ được thì không phải cổng. Bản này đọc
 *     `@thienui/tokens/tokens.json` — dữ liệu đã resolve.
 *
 *  2. MA TRẬN, KHÔNG PHẢI DANH SÁCH CẶP. Bản cũ chỉ kiểm những cặp được KHAI TAY trong TEXT_PAIRS,
 *     nên một badge `--warn` đặt trên `--card` không ai kiểm trong khi test tưởng là đã phủ. Bản này
 *     khai CHÍNH SÁCH GHÉP (token chữ nào thực tế xuất hiện trên mặt nào) rồi tự sinh tổ hợp.
 *     Thêm một mặt mới là mọi token chữ tự được kiểm trên nó.
 */
import { contrast, outOfGamut } from './oklch.mjs';

/**
 * Sàn WCAG 2.2: 1.4.3 chữ thường 4.5:1 · 1.4.11 phi-chữ 3:1.
 *
 * Bậc thứ ba, `decor`, KHÔNG có sàn — và nó không phải một cửa hậu. WCAG 1.4.11 áp cho "thông tin
 * thị giác CẦN THIẾT để nhận ra một component hoặc trạng thái của nó", nên nó MIỄN TRỪ phần trang trí
 * và phần không mang thông tin. Một đường kẻ sợi tóc giữa hai dòng bảng là trang trí: bỏ nó đi thì
 * bảng vẫn đọc được. Còn viền của một ô nhập thì KHÔNG trang trí — nó là thứ duy nhất cho biết ô đó
 * ở đâu, nên nó chịu sàn 3:1. Ranh giới là "bỏ nó đi thì còn nhận ra control không", không phải
 * "nó có phải một đường kẻ không". Bậc `decor` vẫn ĐƯỢC ĐO và báo cáo, chỉ không làm đỏ.
 */
export const AA_TEXT = 4.5;
export const AA_GRAPHIC = 3.0;
export const FLOOR = { text: AA_TEXT, graphic: AA_GRAPHIC, decor: 0 };

/** Mọi mặt mà nội dung có thể nằm trên. Thêm một mặt ở đây = mọi token chữ được kiểm trên nó. */
const SURFACES = ['background', 'card', 'popover', 'sidebar', 'muted', 'secondary', 'accent'];

/**
 * CHÍNH SÁCH GHÉP. `on` = danh sách mặt mà token này THỰC TẾ được render lên.
 * `tier` = 'text' (4.5:1) hoặc 'graphic' (3:1) — chọn theo CÁCH DÙNG, không theo cái gì dễ pass.
 */
export const POLICY = [
  // Chữ thân bài: xuất hiện trên MỌI mặt, nên kiểm trên mọi mặt.
  { token: 'foreground', on: SURFACES, tier: 'text', where: 'chữ thân bài' },
  { token: 'muted-foreground', on: SURFACES, tier: 'text', where: 'chữ phụ — màu chữ được dùng nhiều nhất trong app' },

  // Cặp riêng của từng mặt.
  { token: 'card-foreground', on: ['card'], tier: 'text', where: 'chữ trong card' },
  { token: 'popover-foreground', on: ['popover'], tier: 'text', where: 'chữ trong popover/menu' },
  { token: 'secondary-foreground', on: ['secondary'], tier: 'text', where: 'nhãn nút secondary' },
  { token: 'accent-foreground', on: ['accent'], tier: 'text', where: 'nhãn phần tử đang hover/selected' },
  { token: 'sidebar-foreground', on: ['sidebar'], tier: 'text', where: 'chữ trong sidebar' },
  { token: 'sidebar-accent-foreground', on: ['sidebar-accent'], tier: 'text', where: 'nhãn mục sidebar đang chọn' },
  { token: 'primary-foreground', on: ['primary'], tier: 'text', where: 'nhãn trên nút primary' },
  { token: 'destructive-foreground', on: ['destructive'], tier: 'text', where: 'nhãn trên nút phá hoại' },
  { token: 'sidebar-primary-foreground', on: ['sidebar-primary'], tier: 'text', where: 'nhãn trên nút primary trong sidebar' },

  // Link và 4 token tín hiệu: chúng là CHỮ, nên 4.5:1 — kể cả khi trông như badge.
  { token: 'accent-brand', on: ['background', 'card', 'popover', 'sidebar', 'muted'], tier: 'text', where: 'link, chữ thương hiệu' },
  { token: 'ok', on: ['background', 'card', 'popover', 'muted', 'ok-wash'], tier: 'text', where: 'tín hiệu đúng' },
  { token: 'warn', on: ['background', 'card', 'popover', 'muted', 'warn-wash'], tier: 'text', where: 'tín hiệu một phần' },
  { token: 'alert', on: ['background', 'card', 'popover', 'muted', 'alert-wash'], tier: 'text', where: 'tín hiệu sai' },
  { token: 'info', on: ['background', 'card', 'popover', 'muted', 'info-wash'], tier: 'text', where: 'tín hiệu dễ/đã thuộc' },
  { token: 'destructive', on: ['background', 'card', 'popover'], tier: 'text', where: 'chữ cảnh báo phá hoại' },

  // Phi-chữ: viền, ring, nền đặc. Sàn 3:1.
  // `border` = đường phân tách trang trí: bỏ đi vẫn đọc được nội dung -> miễn trừ 1.4.11, chỉ ĐO.
  { token: 'border', on: ['background', 'card', 'popover', 'sidebar'], tier: 'decor', where: 'viền, đường phân tách — trang trí' },
  // `input` = viền CỦA MỘT CONTROL: nó là thứ duy nhất cho biết ô nhập ở đâu -> chịu sàn 3:1.
  { token: 'input', on: ['background', 'card'], tier: 'graphic', where: 'viền ô nhập — ranh giới của control' },
  { token: 'ring', on: ['background', 'card', 'popover', 'sidebar'], tier: 'graphic', where: 'focus ring — phải thấy được, nếu không bàn phím thành vô dụng' },
  { token: 'sidebar-ring', on: ['sidebar'], tier: 'graphic', where: 'focus ring trong sidebar' },
  { token: 'primary', on: ['background', 'card'], tier: 'graphic', where: 'nền nút primary' },
  { token: 'chart-1', on: ['background', 'card'], tier: 'graphic', where: 'chuỗi biểu đồ 1' },
  { token: 'chart-2', on: ['background', 'card'], tier: 'graphic', where: 'chuỗi biểu đồ 2' },
  { token: 'chart-3', on: ['background', 'card'], tier: 'graphic', where: 'chuỗi biểu đồ 3' },
  { token: 'chart-4', on: ['background', 'card'], tier: 'graphic', where: 'chuỗi biểu đồ 4' },
  { token: 'chart-5', on: ['background', 'card'], tier: 'graphic', where: 'chuỗi biểu đồ 5' },
];

/**
 * Miễn trừ, kèm LÝ DO. Không có lý do thì không được miễn trừ, và một cặp chữ không được
 * chuyển xuống bậc đồ hoạ cho cổng im tiếng — phải sửa token.
 */
export const ALLOW = {
  'claude/*/primary on background':
    'Clay #D97757 trên trang kem đo 2.97:1 — thiếu 0.03 so với sàn 3:1. KHÔNG đổi màu: đây là đúng mã thương hiệu, và sakubun đã giữ nó có chủ ý. Lý do miễn trừ: nút primary luôn mang NHÃN CHỮ ở 5.89:1, nên phần nền không phải thứ duy nhất nhận ra control — 1.4.11 không đòi 3:1 cho một bề mặt đã được nhãn của nó định danh. Miễn trừ này KHÔNG áp cho biểu đồ: ở đó màu LÀ dữ liệu, nên chart-1 dùng bậc `text` của clay (5.40:1) chứ không dùng bậc `solid`.',
  'claude/*/primary-foreground on primary':
    'Lệch CÓ Ý: Claude ship chữ TRẮNG trên clay (3.12:1, dưới sàn). Ta giữ đúng #D97757 và đổi nhãn sang ink #141413 = 5.89:1. Nút đúng màu, nhãn tối. Cặp này PASS — mục này chỉ để ghi lại quyết định.',
};

/** Chạy cổng. Trả về { pass, results, failures }. Không throw — người gọi quyết định làm gì. */
export function checkContrast(tokens, { policy = POLICY, allow = ALLOW } = {}) {
  const results = [];
  for (const [themeName, modes] of Object.entries(tokens.themes)) {
    for (const [mode, t] of Object.entries(modes)) {
      for (const rule of policy) {
        const fg = t[rule.token];
        if (!fg) {
          results.push({ theme: themeName, mode, fg: rule.token, bg: '—', ratio: 0, floor: 0, pass: false,
            reason: `token "--${rule.token}" không tồn tại trong theme`, where: rule.where });
          continue;
        }
        for (const bgName of rule.on) {
          const bg = t[bgName];
          if (!bg) {
            results.push({ theme: themeName, mode, fg: rule.token, bg: bgName, ratio: 0, floor: 0, pass: false,
              reason: `mặt "--${bgName}" không tồn tại trong theme`, where: rule.where });
            continue;
          }
          const floor = FLOOR[rule.tier];
          const ratio = contrast(fg, bg);
          const key = `${themeName}/${mode}/${rule.token} on ${bgName}`;
          const wild = `${themeName}/*/${rule.token} on ${bgName}`;
          results.push({
            theme: themeName, mode, fg: rule.token, bg: bgName, tier: rule.tier,
            ratio: Number(ratio.toFixed(3)), floor, pass: ratio >= floor,
            allowed: allow[key] ?? allow[wild] ?? null, where: rule.where,
          });
        }
      }
    }
  }
  const failures = results.filter((r) => !r.pass && !r.allowed);
  return { pass: failures.length === 0, results, failures };
}

/** Token nào khai màu ngoài gamut sRGB — máy không hiện được đúng màu đó. */
export function checkGamut(tokens) {
  const bad = [];
  for (const [path, v] of Object.entries(tokens.primitive)) {
    if (typeof v !== 'string' || !v.startsWith('oklch(')) continue;
    if (outOfGamut(v)) bad.push({ path, value: v });
  }
  return { pass: bad.length === 0, outOfGamut: bad };
}

export { contrast, oklchToLinearRgb, luminance, outOfGamut, solveLightness } from './oklch.mjs';
export { checkContrast, checkGamut, POLICY, ALLOW, AA_TEXT, AA_GRAPHIC, FLOOR } from './contrast.mjs';
export { runPatternLock, runCheck, loadRegistry } from './pattern-lock.mjs';
export { checkCanonicals } from './canonical.mjs';

/**
 * OKLCH -> linear sRGB -> độ sáng tương đối WCAG -> tỉ số tương phản.
 *
 * Thuần số học, không browser, không screenshot, không LLM chấm ảnh: một "yêu cầu thẩm mỹ" biến
 * thành một check tất định. Ma trận của Björn Ottosson.
 */

/** oklch(L C H [/ A]) -> [r,g,b] trong linear sRGB, đã clamp về [0,1]. */
export function oklchToLinearRgb(value) {
  const m = /oklch\(\s*([\d.]+)\s+([\d.]+)\s+([\d.]+)/.exec(value);
  if (!m) throw new Error(`không phải màu oklch(): ${value}`);
  const [L, C, hDeg] = [Number(m[1]), Number(m[2]), Number(m[3])];
  const h = (hDeg * Math.PI) / 180;
  const a = C * Math.cos(h);
  const b = C * Math.sin(h);
  const l = (L + 0.3963377774 * a + 0.2158037573 * b) ** 3;
  const m2 = (L - 0.1055613458 * a - 0.0638541728 * b) ** 3;
  const s = (L - 0.0894841775 * a - 1.291485548 * b) ** 3;
  const clamp = (v) => Math.min(1, Math.max(0, v));
  return [
    clamp(4.0767416621 * l - 3.3077115913 * m2 + 0.2309699292 * s),
    clamp(-1.2684380046 * l + 2.6097574011 * m2 - 0.3413193965 * s),
    clamp(-0.0041960863 * l - 0.7034186147 * m2 + 1.707614701 * s),
  ];
}

/** Độ sáng tương đối WCAG. Linear sRGB đã đúng dạng công thức cần. */
export const luminance = ([r, g, b]) => 0.2126 * r + 0.7152 * g + 0.0722 * b;

/** Tỉ số tương phản WCAG 2.x giữa hai màu oklch(). */
export function contrast(fg, bg) {
  const a = luminance(oklchToLinearRgb(fg));
  const b = luminance(oklchToLinearRgb(bg));
  const [hi, lo] = a > b ? [a, b] : [b, a];
  return (hi + 0.05) / (lo + 0.05);
}

/** Ngoài gamut sRGB? Dùng để cảnh báo token khai màu máy không hiện được. */
export function outOfGamut(value) {
  const m = /oklch\(\s*([\d.]+)\s+([\d.]+)\s+([\d.]+)/.exec(value);
  if (!m) return false;
  const [L, C, hDeg] = [Number(m[1]), Number(m[2]), Number(m[3])];
  const h = (hDeg * Math.PI) / 180;
  const a = C * Math.cos(h), b = C * Math.sin(h);
  const l = (L + 0.3963377774 * a + 0.2158037573 * b) ** 3;
  const m2 = (L - 0.1055613458 * a - 0.0638541728 * b) ** 3;
  const s = (L - 0.0894841775 * a - 1.291485548 * b) ** 3;
  const raw = [
    4.0767416621 * l - 3.3077115913 * m2 + 0.2309699292 * s,
    -1.2684380046 * l + 2.6097574011 * m2 - 0.3413193965 * s,
    -0.0041960863 * l - 0.7034186147 * m2 + 1.707614701 * s,
  ];
  return raw.some((v) => v < -0.002 || v > 1.002);
}

/**
 * Giải L cao nhất (hoặc thấp nhất, ở dark) mà một màu còn vượt `target` trên MỌI nền trong `grounds`.
 * Đây là công cụ để SỬA một token trượt cổng, thay vì mò bằng tay — sakubun giải mấy giá trị này
 * bằng tay rồi ghi kết quả vào comment, nên con số đúng một lần rồi mục dần.
 */
export function solveLightness(chroma, hue, grounds, target = 4.5, { prefer = 'light' } = {}) {
  const ok = (L) => grounds.every((g) => contrast(`oklch(${L} ${chroma} ${hue})`, g) >= target);
  let lo = 0, hi = 1;
  for (let i = 0; i < 60; i++) {
    const mid = (lo + hi) / 2;
    // ở light ta muốn L LỚN nhất còn đạt; ở dark ta muốn L NHỎ nhất còn đạt
    if (prefer === 'light') (ok(mid) ? (lo = mid) : (hi = mid));
    else (ok(mid) ? (hi = mid) : (lo = mid));
  }
  const L = prefer === 'light' ? lo : hi;
  return ok(L) ? Number(L.toFixed(4)) : null;
}

/**
 * Bộ chạy cho LUẬT UI ĐÃ KHOÁ.
 *
 * Ý tưởng gốc từ `docs/ui-patterns.json` + `lib/ui-pattern-lock.test.ts` của sakubun, và nó là tài sản
 * thật của repo đó: một registry chỉ-thêm (append-only) các luật UI mà người dùng KHÔNG BAO GIỜ phải
 * nhắc lại. Mỗi luật mang `rule` (luật là gì) · `why` (vì sao — để sau này không ai gỡ nó vì tưởng vô
 * nghĩa) · `canonical` (chỗ làm đúng, để copy) · `check` (máy chạy được) · `allow` (ngoại lệ KÈM LÝ DO).
 *
 * Hai bên đọc cùng một file: bộ chạy này làm đỏ `pnpm test`, và một hook hiện toàn bộ luật trước lần
 * ghi UI đầu tiên của mỗi phiên. Một luật chỉ có chữ thì là một lời nhắc; có `check` thì là một cổng.
 */
import { readFileSync, globSync } from 'node:fs';
import { basename, resolve } from 'node:path';

const DEFAULT_SCOPE = ['**/*.tsx', '**/*.ts', '**/*.jsx', '**/*.js', '**/*.css'];
const IGNORE = ['**/node_modules/**', '**/dist/**', '**/.next/**', '**/.turbo/**', '**/*.d.ts'];
/**
 * Thư mục KHÔNG BAO GIỜ đi vào. `IGNORE` lọc từng file SAU khi glob đã duyệt cả cây; ở một app Next có
 * `node_modules` và `.next` thì phần duyệt đó chiếm gần hết thời gian (đo trên sakubun: 46 giây cho
 * một lượt, 1 giây khi cắt nhánh). Cắt ở đây là để cổng đủ nhanh để chạy trong `npm test`.
 */
const SKIP_DIRS = new Set(['node_modules', 'dist', '.next', '.turbo', '.git']);
const skipDir = (p) => SKIP_DIRS.has(basename(typeof p === 'string' ? p : p.name));

/**
 * Khớp glob tối giản cho danh sách loại trừ.
 *
 * `**\/` phải khớp KHÔNG đoạn nào luôn, không chỉ một-hoặc-nhiều: `**\/node_modules/**` phải bắt được
 * `node_modules/pkg/a.tsx` (nằm ngay gốc repo), không chỉ `a/node_modules/pkg/a.tsx`. Dịch nó thành
 * `.*\/` sẽ đòi một dấu gạch đứng trước và bỏ sót đúng trường hợp phổ biến nhất.
 */
function matchSimple(pattern, path) {
  let rx = '';
  let i = 0;
  while (i < pattern.length) {
    if (pattern.startsWith('**/', i)) { rx += '(?:[^/]+/)*'; i += 3; }
    else if (pattern.startsWith('**', i)) { rx += '.*'; i += 2; }
    else if (pattern[i] === '*') { rx += '[^/]*'; i += 1; }
    else { rx += pattern[i].replace(/[.+^${}()|[\]\\?]/, '\\$&'); i += 1; }
  }
  return new RegExp('^' + rx + '$').test(path);
}

/**
 * `exclude` tồn tại vì glob không diễn tả được "mọi nơi TRỪ một thư mục" — và đó là phạm vi đúng của
 * phần lớn luật văn phong: chúng áp cho code TA VIẾT, không áp cho code vendor được kéo lại từ
 * upstream. Không có nó thì mỗi luật phải liệt kê tay từng thư mục được phép, và lần thêm thư mục
 * thứ tư là lần một luật âm thầm ngừng áp.
 */
function filesFor(root, scope, exclude = []) {
  const out = new Set();
  for (const pat of scope) {
    for (const f of globSync(pat, { cwd: root, exclude: skipDir })) {
      if (IGNORE.some((i) => matchSimple(i, f))) continue;
      if (exclude.some((e) => matchSimple(e, f))) continue;
      out.add(f);
    }
  }
  return [...out].sort();
}

/**
 * Tìm chỗ kết thúc của thẻ JSX mở bắt đầu ở `start` (vị trí của `<`). Trả về `{ end, selfClosing }`.
 *
 * Phải đi qua ngoặc nhọn và chuỗi chứ không tìm `>` đầu tiên: `onClick={() => x}` chứa một `>` nằm
 * TRONG thuộc tính, và tìm ngây thơ sẽ cắt thẻ ở đó rồi đọc nhầm phần còn lại là con của nó.
 */
function tagEnd(text, start) {
  let depth = 0;
  let quote = null;
  for (let i = start + 1; i < text.length; i++) {
    const c = text[i];
    if (quote) {
      if (c === '\\') i++;
      else if (c === quote) quote = null;
    } else if (c === '"' || c === "'" || c === '`') quote = c;
    else if (c === '{') depth++;
    else if (c === '}') depth--;
    else if (c === '>' && depth === 0) return { end: i, selfClosing: text[i - 1] === '/' };
  }
  return { end: text.length - 1, selfClosing: true };
}

/** Tên được import từ một module — gồm cả bí danh: `import { Image as ImageIcon }` cho `ImageIcon`. */
function importedNames(text, from) {
  const names = new Set();
  const rx = new RegExp(`import\\s*\\{([^}]*)\\}\\s*from\\s*['"]${from.replace(/[.*+?^${}()|[\]\\/]/g, '\\$&')}['"]`, 'g');
  for (const m of text.matchAll(rx)) {
    for (const part of m[1].split(',')) {
      const p = part.trim();
      if (!p || p.startsWith('type ')) continue;
      const alias = p.split(/\s+as\s+/).pop().trim();
      if (/^[A-Z]\w*$/.test(alias)) names.add(alias);
    }
  }
  return names;
}

/**
 * Tách token class ra khỏi văn bản của một thẻ, rồi bỏ tiền tố biến thể (`md:`, `[&_svg]:`,
 * `data-[state=open]:`). Bỏ tới dấu `:` CUỐI nằm ngoài ngoặc vuông — `[&_svg]:size-4` phải ra `size-4`,
 * còn `size-[var(--a)]` thì giữ nguyên.
 */
function classTokens(tagText) {
  const out = [];
  for (const raw of tagText.split(/[\s"'`{}(),]+/)) {
    if (!raw) continue;
    let depth = 0;
    let cut = -1;
    for (let i = 0; i < raw.length; i++) {
      if (raw[i] === '[') depth++;
      else if (raw[i] === ']') depth--;
      else if (raw[i] === ':' && depth === 0) cut = i;
    }
    out.push(raw.slice(cut + 1));
  }
  return out;
}

/**
 * Một `<Tên` chỉ là thẻ JSX khi KHÔNG đứng ngay sau một định danh: `useState<Item>()` và `Array<Badge>`
 * là generic của TypeScript, và đếm chúng là thẻ mở sẽ khiến mọi icon phía sau bị coi là nằm trong
 * `Item` hay `Badge`.
 */
const JSX_OPEN = (name) => new RegExp(`(?<![\\w.$\\]])<(${name})(?=[\\s/>])`, 'g');

/**
 * Bộ chạy cho luật về CLASS TRÊN MỘT LOẠI THẺ JSX — thứ regex theo dòng không diễn tả được, vì icon
 * lucide được import với tên trần (`Search`, `X`) và một thẻ JSX hay trải trên nhiều dòng.
 *
 *   tags        — tên thẻ cụ thể, ví dụ `["Button"]`
 *   tagsFrom    — module mà MỌI tên import từ nó đều là thẻ cần kiểm, ví dụ `"lucide-react"`
 *   tagSuffix   — tên kết thúc bằng hậu tố này cũng là thẻ cần kiểm (`Icon` bắt `<item.icon>` đã gán
 *                 vào biến `Icon`, và `<ImageIcon>`)
 *   forbidClass — regex cho token class bị cấm (đã bỏ tiền tố biến thể)
 *   allowClass  — regex cho token class được miễn dù khớp `forbidClass`
 *   inside      — nếu có: chỉ tính khi thẻ nằm TRONG một trong các thẻ cha này
 */
function checkJsxClass(text, chk) {
  const names = new Set(chk.tags ?? []);
  if (chk.tagsFrom) for (const n of importedNames(text, chk.tagsFrom)) names.add(n);
  const isTag = (n) => names.has(n) || (chk.tagSuffix && n.endsWith(chk.tagSuffix));
  const forbid = new RegExp(chk.forbidClass);
  const allow = chk.allowClass ? new RegExp(chk.allowClass) : null;
  const found = [];
  for (const m of text.matchAll(JSX_OPEN('[A-Z]\\w*'))) {
    if (!isTag(m[1])) continue;
    const { end } = tagEnd(text, m.index);
    const tagText = text.slice(m.index + m[0].length, end);
    const bad = classTokens(tagText).filter((t) => forbid.test(t) && !(allow && allow.test(t)));
    if (!bad.length) continue;
    if (chk.inside && !chk.inside.some((p) => openCount(text, p, m.index) > 0)) continue;
    found.push({ index: m.index, classes: bad, tag: m[1] });
  }
  return found;
}

/** Số thẻ `<parent>` còn mở tại vị trí `at` — thẻ tự đóng `<Button />` không chứa được con nên không tính. */
function openCount(text, parent, at) {
  const before = text.slice(0, at);
  let open = 0;
  for (const m of before.matchAll(JSX_OPEN(parent))) {
    if (!tagEnd(before, m.index).selfClosing) open++;
  }
  const closed = before.match(new RegExp(`</${parent}\\s*>`, 'g'))?.length ?? 0;
  return open - closed;
}

/**
 * Chạy một luật. Trả về danh sách vi phạm `{file, line, excerpt}`.
 *
 * `check.kind`:
 *   forbid        — `pattern` KHÔNG được xuất hiện trong phạm vi
 *   require       — `pattern` PHẢI xuất hiện trong mỗi file thuộc phạm vi
 *   forbid-import — file trong `check.from` không được import đường dẫn khớp `check.pattern`
 *   require-with  — file khớp `when` thì phải khớp cả `then`
 *   jsx-class     — thẻ JSX được chọn không được mang token class bị cấm (xem `checkJsxClass`)
 *
 * `check.exclude` bỏ qua một số glob trong phạm vi — dùng để loại code vendor khỏi luật văn phong.
 */
export function runCheck(root, pattern) {
  const chk = pattern.check;
  if (!chk) return { skipped: 'luật chỉ có chữ, không có check máy chạy được', violations: [] };
  const scope = chk.files ?? DEFAULT_SCOPE;
  const exclude = chk.exclude ?? [];
  const allow = pattern.allow ?? {};
  // Khoá của `allow` là đường dẫn HOẶC glob. Glob cần thiết vì cùng một file sống ở
  // `apps/docs/registry/...` trong thienui nhưng ở `apps/web/registry/...` trong project tiêu thụ —
  // ghi cứng `apps/docs/` thì ngoại lệ không bao giờ khớp ở nơi nó được dùng thật.
  const allowed = (f) => f in allow || Object.keys(allow).some((k) => k.includes('*') && matchSimple(k, f));
  const violations = [];

  if (chk.kind === 'forbid' || chk.kind === 'forbid-import') {
    const rx = new RegExp(chk.pattern);
    const files = filesFor(root, chk.kind === 'forbid-import' ? (chk.from ?? scope) : scope, exclude);
    for (const f of files) {
      if (allowed(f)) continue;
      const lines = readFileSync(resolve(root, f), 'utf8').split('\n');
      for (let i = 0; i < lines.length; i++) {
        if (rx.test(lines[i])) violations.push({ file: f, line: i + 1, excerpt: lines[i].trim().slice(0, 120) });
      }
    }
  } else if (chk.kind === 'require') {
    const rx = new RegExp(chk.pattern);
    for (const f of filesFor(root, scope, exclude)) {
      if (allowed(f)) continue;
      if (!rx.test(readFileSync(resolve(root, f), 'utf8'))) {
        violations.push({ file: f, line: 0, excerpt: 'thiếu mẫu: ' + chk.pattern });
      }
    }
  } else if (chk.kind === 'require-with') {
    // Nếu `when` khớp trong một file thì `then` cũng phải khớp trong file đó.
    const when = new RegExp(chk.when);
    const then = new RegExp(chk.then);
    for (const f of filesFor(root, scope, exclude)) {
      if (allowed(f)) continue;
      const text = readFileSync(resolve(root, f), 'utf8');
      if (when.test(text) && !then.test(text)) {
        violations.push({ file: f, line: 0, excerpt: 'khớp "' + chk.when + '" nhưng thiếu "' + chk.then + '"' });
      }
    }
  } else if (chk.kind === 'jsx-class') {
    for (const f of filesFor(root, chk.files ?? ['**/*.tsx', '**/*.jsx'], exclude)) {
      if (allowed(f)) continue;
      const text = readFileSync(resolve(root, f), 'utf8');
      for (const v of checkJsxClass(text, chk)) {
        const line = text.slice(0, v.index).split('\n').length;
        violations.push({ file: f, line, excerpt: `<${v.tag}> mang ${v.classes.join(' ')}` });
      }
    }
  } else if (chk.kind === 'manual') {
    // Luật người review, không máy. Vẫn nằm trong registry vì hook phải HIỆN nó ra trước khi ghi UI —
    // và vì `why` của nó là thứ ngăn người sau gỡ luật vì tưởng nó vô nghĩa.
    return { manual: true, violations: [] };
  } else {
    return { error: 'check.kind không biết: ' + chk.kind, violations: [] };
  }
  return { violations };
}

/** Chạy cả registry. Trả về { pass, byPattern, total }. */
export function runPatternLock(root, registry) {
  const byPattern = [];
  let total = 0;
  for (const p of registry.patterns) {
    const r = runCheck(root, p);
    total += r.violations.length;
    byPattern.push({ id: p.id, rule: p.rule, canonical: p.canonical, ...r });
  }
  return { pass: total === 0, byPattern, total };
}

export const loadRegistry = (file) => JSON.parse(readFileSync(file, 'utf8'));

